const app = express();

// Request logging. There was no logger of any kind before this, so a request
// that 404'd or 500'd left no trace in the terminal at all. Registered as the
// very first middleware so it also catches body-parser rejections that never
// reach a route. Set QUIET_LOGS=1 in server/.env to silence it.
if (process.env.QUIET_LOGS !== '1') {
  app.use((req, res, next) => {
    const startedAt = process.hrtime.bigint();
    res.on('finish', () => {
      const ms = Number(process.hrtime.bigint() - startedAt) / 1e6;
      const status = res.statusCode;
      const colour =
        status >= 500 ? 31 : status >= 400 ? 33 : status >= 300 ? 36 : 32;
      console.log(
        `\x1b[90m${new Date().toISOString().slice(11, 19)}\x1b[0m ` +
          `${req.method.padEnd(6)} ${req.originalUrl} ` +
          `\x1b[${colour}m${status}\x1b[0m ${ms.toFixed(1)}ms`
      );
    });
    next();
  });
}

