// Global error handler. Without this, Express's built-in finalhandler includes
// the full stack trace in the response body whenever NODE_ENV !== 'production'
// — and NODE_ENV is never set anywhere in this project. A malformed JSON body
// was enough to return absolute server paths to the client.
//
// Mongoose validation failures are mapped to 400 rather than 500: they are
// user input errors (a height outside 100-250cm, a swapped blood-pressure
// pair), and returning 500 made the UI report the user's own typo as a server
// fault.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (err && err.name === 'ValidationError') {
    const detail = Object.values(err.errors || {})
      .map((e) => e.message)
      .join('; ');
    return res.status(400).json({ msg: detail || 'Invalid submission' });
  }
  if (err && err.name === 'CastError') {
    return res.status(400).json({ msg: 'Malformed identifier' });
  }
  if (err && err.type === 'entity.parse.failed') {
    return res.status(400).json({ msg: 'Malformed JSON body' });
  }
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

